css:
@page {
    size: A4;
    margin: 10mm 10mm 12mm 10mm;
}
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}
body {
    font-family: serif !important;
    font-size: 9pt;
    color: #000;
}
.page {
    width: 100%;
}
.top-table {
    width: 100%;
    margin-bottom: 10px;
}
.top-table td {
    vertical-align: top;
}
.company-block {
    font-size: 8pt;
}
.company-name {
    font-size: 11pt;
    font-weight: bold;
}
.title {
    font-size: 16pt;
    font-weight: bold;
    letter-spacing: 4px;
    text-align: center;
}
.code-header {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    font-size: 8pt;
}
.code-header td {
    border-left: 1px solid #000;
    padding: 3px 4px;
    text-align: center;
}
.code-header td:first-child {
    border-left: none;
}
.meta-row {
    width: 100%;
    font-size: 8pt;
    margin-bottom: 8px;
}
.meta-row td {
    padding: 2px 4px;
}
.meta-right {
    text-align: right;
}
.paragraph {
    font-size: 8pt;
    margin-bottom: 6px;
}
.paragraph span {
    font-weight: bold;
}

table.grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 8pt;
}
table.grid th,
table.grid td {
    border: 1px solid #000;
    padding: 3px 4px;
    vertical-align: top;
}
table.grid th {
    text-align: center;
    font-weight: bold;
}

.payment-block {
    width: 100%;
    border-collapse: collapse;
    font-size: 8pt;
    margin-top: 2px;
}
.payment-block td {
    border: 1px solid #000;
    padding: 3px 4px;
}

.small {
    font-size: 7.5pt;
}

.bottom-grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 8pt;
    margin-top: 4px;
}
.bottom-grid th,
.bottom-grid td {
    border: 1px solid #000;
    padding: 3px 4px;
    vertical-align: top;
}

.for-customs-row {
    height: 70px;
}

.sign-box {
    text-align: center;
    padding-top: 30px;
    font-size: 8pt;
}

.footer-declaration {
    font-size: 8pt;
    margin-top: 6px;
}

.foot-line {
    width: 100%;
    text-align: center;
    font-size: 7.5pt;
    margin-top: 18px;
}
